//! Byte classification helpers.
//!
//! The C++ side stores the domain in a `std::string`, i.e. a plain byte
//! buffer with no encoding attached. Every classification below therefore
//! works on raw bytes so that inputs which are not valid UTF-8 behave the
//! same way they do in the original binary.

/// Largest byte value that is still a 7-bit ASCII code point.
const ASCII_MAX: u8 = 0x7F;

/// True when `byte` is part of the 7-bit ASCII range.
#[inline]
pub fn is_ascii_byte(byte: u8) -> bool {
    byte <= ASCII_MAX
}

/// True when every byte of `domain` is 7-bit ASCII.
///
/// An empty input is vacuously ASCII, matching the C++ behaviour.
pub fn all_ascii(domain: &[u8]) -> bool {
    domain.iter().copied().all(is_ascii_byte)
}

/// True when at least one byte of `domain` falls outside the ASCII range.
///
/// This is what marks a domain as internationalised: the U-label form of an
/// IDN carries non-ASCII code points, whereas its A-label (`xn--`) form does
/// not and is reported as a plain ASCII domain.
pub fn any_non_ascii(domain: &[u8]) -> bool {
    domain.iter().copied().any(|byte| !is_ascii_byte(byte))
}

