//! Length based validation of domains and labels.
//!
//! Both limits are measured in bytes, exactly like `std::string::size()`,
//! so a multi-byte UTF-8 label is bounded by its encoded length rather than
//! by its code point count.

/// Maximum size, in bytes, of a whole domain name.
pub const MAX_DOMAIN_LEN: usize = 255;

/// Maximum size, in bytes, of a single label.
pub const MAX_LABEL_LEN: usize = 63;

/// True when `domain` is a non-empty byte string that fits the domain limit.
pub fn valid_domain(domain: &[u8]) -> bool {
    !domain.is_empty() && domain.len() <= MAX_DOMAIN_LEN
}

/// True when `label` is a non-empty byte string that fits the label limit.
pub fn valid_label(label: &[u8]) -> bool {
    !label.is_empty() && label.len() <= MAX_LABEL_LEN
}

