//! Re-implementation of the `idna::` helpers used by `test4.cpp`.
//!
//! The original C++ API takes a `std::string`, which is a byte buffer, so
//! every entry point here accepts anything that borrows as bytes (`&str`,
//! `String`, `&[u8]`, ...) and answers purely in terms of those bytes.

pub mod charset;
pub mod validate;

/// Checks whether `domain` is an acceptable domain name.
///
/// A domain must be non-empty and at most
/// [`validate::MAX_DOMAIN_LEN`] bytes long.
pub fn is_valid_domain<S: AsRef<[u8]> + ?Sized>(domain: &S) -> bool {
    validate::valid_domain(domain.as_ref())
}

/// Checks whether `label` is an acceptable single label.
///
/// A label must be non-empty and at most
/// [`validate::MAX_LABEL_LEN`] bytes long.
pub fn is_valid_label<S: AsRef<[u8]> + ?Sized>(label: &S) -> bool {
    validate::valid_label(label.as_ref())
}

/// Checks whether `domain` consists solely of ASCII bytes.
pub fn is_ascii_domain<S: AsRef<[u8]> + ?Sized>(domain: &S) -> bool {
    charset::all_ascii(domain.as_ref())
}

/// Checks whether `domain` carries at least one non-ASCII byte, i.e. whether
/// it is written in its internationalised (U-label) form.
pub fn is_idn_domain<S: AsRef<[u8]> + ?Sized>(domain: &S) -> bool {
    charset::any_non_ascii(domain.as_ref())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn matches_documented_examples() {
        for ascii in ["example.com", "test.org", "subdomain.example.com"] {
            assert_eq!(
                (
                    is_valid_domain(ascii),
                    is_valid_label(ascii),
                    is_ascii_domain(ascii),
                    is_idn_domain(ascii)
                ),
                (true, true, true, false)
            );
        }

        let idn = "例子.测试";
        assert_eq!(
            (
                is_valid_domain(idn),
                is_valid_label(idn),
                is_ascii_domain(idn),
                is_idn_domain(idn)
            ),
            (true, true, false, true)
        );
    }

    #[test]
    fn empty_input_is_invalid_but_ascii() {
        assert!(!is_valid_domain(""));
        assert!(!is_valid_label(""));
        assert!(is_ascii_domain(""));
        assert!(!is_idn_domain(""));
    }

    #[test]
    fn length_limits_are_measured_in_bytes() {
        assert!(is_valid_label(&"a".repeat(63)));
        assert!(!is_valid_label(&"a".repeat(64)));
        assert!(is_valid_domain(&"a".repeat(255)));
        assert!(!is_valid_domain(&"a".repeat(256)));

        // 21 * 3 == 63 bytes, still a valid label; 22 * 3 == 66 is not.
        assert!(is_valid_label(&"例".repeat(21)));
        assert!(!is_valid_label(&"例".repeat(22)));
    }

    #[test]
    fn a_labels_are_plain_ascii() {
        assert!(is_ascii_domain("xn--fsq.com"));
        assert!(!is_idn_domain("xn--fsq.com"));
    }

    #[test]
    fn non_utf8_bytes_count_as_idn() {
        let raw: &[u8] = &[b'a', 0xFF, b'b'];
        assert!(!is_ascii_domain(raw));
        assert!(is_idn_domain(raw));
        assert!(is_valid_domain(raw));
    }
}

