//! Command line handling for the `test4` entry point.

use std::ffi::OsString;

/// Reads the optional positional `domain` argument.
///
/// The C++ program reads `argv[1]` straight into a `std::string`, so it never
/// rejects an argument for not being valid UTF-8. `std::env::args()` would
/// panic on such input, therefore the arguments are taken as `OsString`s and
/// turned back into the raw bytes the original program would have seen.
pub fn domain_arg(default: &str) -> Vec<u8> {
    let mut args = std::env::args_os();
    args.next(); // argv[0]

    match args.next() {
        Some(arg) => into_bytes(arg),
        None => default.as_bytes().to_vec(),
    }
}

#[cfg(unix)]
fn into_bytes(arg: OsString) -> Vec<u8> {
    use std::os::unix::ffi::OsStringExt;
    arg.into_vec()
}

#[cfg(not(unix))]
fn into_bytes(arg: OsString) -> Vec<u8> {
    arg.to_string_lossy().into_owned().into_bytes()
}

