const RS: &str = "/output/test4";

fn run(exe: &str, args: &[Vec<u8>]) -> (Vec<u8>, Option<i32>) {
    let os: Vec<OsString> = args.iter().cloned().map(OsString::from_vec).collect();
    let out = Command::new(exe).args(&os).output().expect("spawn");
    (out.stdout, out.status.code())
}

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }
    fn below(&mut self, n: usize) -> usize {
        (self.next() % n as u64) as usize
    }
}

fn main() {
    let mut cases: Vec<Vec<Vec<u8>>> = vec![vec![]];

    let literals: Vec<String> = {
        let mut v: Vec<String> = [
            "example.com", "test.org", "subdomain.example.com",
            "deep.nested.subdomain.example.com", "例子.测试", "", "a", ".", "..",
            "example.", "..a..", "-x-", "xn--fsq.com", "XN--FSQ.COM", "xn--",
            "münchen.de", "日本.jp", "Ünïcödé.example", "a b", "a\tb", "a\nb", "0",
            "-", "_", "~", "!@#$%^&*()", "127.0.0.1", "::1", "[::1]", "localhost",
            "LOCALHOST", "例", "ω", "🚀.com", "a.b.c", "-lead.com", "trail-.com",
        ]
        .iter()
        .map(|s| s.to_string())
        .collect();
        for n in [0, 1, 62, 63, 64, 65, 126, 127, 128, 253, 254, 255, 256, 257, 300] {
            v.push("a".repeat(n));
            v.push("例".repeat(n));
            v.push(format!("{}.com", "a".repeat(n)));
        }
        v
    };
    for s in &literals {
        cases.push(vec![s.clone().into_bytes()]);
    }
    cases.push(vec![b"a".to_vec(), b"b".to_vec()]);
    cases.push(vec![b"example.com".to_vec(), b"extra".to_vec(), b"args".to_vec()]);

    // Every non-NUL byte, alone and embedded (NUL cannot cross an argv boundary).
    for b in 1u16..256 {
        cases.push(vec![vec![b as u8]]);
        cases.push(vec![vec![b'a', b as u8, b'b']]);
