fn run(exe: &str, args: &[Vec<u8>]) -> (Vec<u8>, Option<i32>) {
    let os: Vec<OsString> = args.iter().cloned().map(OsString::from_vec).collect();
    let out = Command::new(exe).args(&os).output().expect("spawn");
    (out.stdout, out.status.code())
}

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }
    fn below(&mut self, n: usize) -> usize {
        (self.next() % n as u64) as usize
    }
}

fn main() {
    let mut cases: Vec<Vec<Vec<u8>>> = vec![vec![]];

    let literals: Vec<String> = {
        let mut v: Vec<String> = [
            "example.com", "test.org", "subdomain.example.com",
            "deep.nested.subdomain.example.com", "例子.测试", "", "a", ".", "..",
            "example.", "..a..", "-x-", "xn--fsq.com", "XN--FSQ.COM", "xn--",
            "münchen.de", "日本.jp", "Ünïcödé.example", "a b", "a\tb", "a\nb", "0",
            "-", "_", "~", "!@#$%^&*()", "127.0.0.1", "::1", "[::1]", "localhost",
            "LOCALHOST", "例", "ω", "🚀.com", "a.b.c", "-lead.com", "trail-.com",
        ]
        .iter()
        .map(|s| s.to_string())
        .collect();
        for n in [0, 1, 62, 63, 64, 65, 126, 127, 128, 253, 254, 255, 256, 257, 300] {
            v.push("a".repeat(n));
            v.push("例".repeat(n));
            v.push(format!("{}.com", "a".repeat(n)));
        }
        v
    };
    for s in &literals {
        cases.push(vec![s.clone().into_bytes()]);
    }
    cases.push(vec![b"a".to_vec(), b"b".to_vec()]);
    cases.push(vec![b"example.com".to_vec(), b"extra".to_vec(), b"args".to_vec()]);

    // Every non-NUL byte, alone and embedded (NUL cannot cross an argv boundary).
    for b in 1u16..256 {
        cases.push(vec![vec![b as u8]]);
        cases.push(vec![vec![b'a', b as u8, b'b']]);
    }

    // Random raw-byte strings clustered on the length boundaries.
    let mut rng = Rng(0x9E3779B97F4A7C15);
    let lens = [0, 1, 2, 62, 63, 64, 65, 253, 254, 255, 256, 257];
    for _ in 0..3000 {
        let n = if rng.below(2) == 0 {
            lens[rng.below(lens.len())]
        } else {
            rng.below(320)
        };
        let s: Vec<u8> = (0..n).map(|_| 1 + rng.below(255) as u8).collect();
        cases.push(vec![s]);
    }

    // Random UTF-8 strings from a domain-ish alphabet.
    let alpha: Vec<&str> = "a b z A Z 0 9 - . _ 例 测 試 🚀 ü Ü ~ ! /"
        .split(' ')
        .collect();
    for _ in 0..3000 {
        let n = rng.below(130);
        let s: String = (0..n).map(|_| alpha[rng.below(alpha.len())]).collect();
        cases.push(vec![s.into_bytes()]);
    }

    let (mut total, mut bad) = (0usize, 0usize);
    for c in &cases {
        let a = run(CPP, c);
        let b = run(RS, c);
        total += 1;
        if a != b {
            bad += 1;
            if bad <= 10 {
                println!(
                    "MISMATCH args={:?}\n  cpp={:?}\n  rs ={:?}",
                    c.iter().map(|x| String::from_utf8_lossy(x).into_owned()).collect::<Vec<_>>(),
                    (String::from_utf8_lossy(&a.0), a.1),
                    (String::from_utf8_lossy(&b.0), b.1),
                );
            }
        }
    }
    println!("compared {total} cases, {bad} mismatches");
}
